make_prediction <- function(endpoint,letter,domain){d<-read_input("performance.csv");d<-d[d$endpoint==endpoint,];mods<-c("Structure","Reference","ReferenceStructure","PPSD","ReferencePPSD","Full");d<-d[match(mods,d$model),];labels<-c("Structure",paste("Baseline",domain),paste0("Baseline ",domain," + structure"),"PPSD",paste0("Baseline ",domain," + PPSD"),paste0("Baseline ",domain," + structure\n+ clinical + PPSD"));d$label<-factor(labels,levels=rev(labels));d$model<-factor(d$model,levels=mods);sig<-read_input("significance_tests.csv");sig<-sig[sig$endpoint==endpoint,];sig$stars[is.na(sig$stars)]<-"";d$stars<-"";d$stars[d$model=="ReferencePPSD"]<-sig$stars[sig$comparison=="PPSD_added_to_reference"];d$stars[d$model=="Full"]<-sig$stars[sig$comparison=="StructureClinical_added_to_reference_PPSD"]
 ggplot(d,aes(r2,label,fill=model))+geom_col(width=.55,alpha=.9)+geom_errorbar(aes(xmin=r2_lo,xmax=r2_hi),orientation="y",width=.13,linewidth=.35,color=CFG$ink)+geom_text(aes(x=r2_hi+.012,label=paste0(sprintf("%.3f",r2),stars)),size=mm_pt(CFG$font_pt),hjust=0,family=CFG$family)+geom_vline(xintercept=0,linewidth=.25,color=CFG$grey)+scale_fill_manual(values=c(Structure=CFG$blue,Reference=CFG$grey,ReferenceStructure=CFG$teal,PPSD=CFG$red,ReferencePPSD="#D9A441",Full=CFG$purple))+scale_x_continuous(limits=c(-.04,.68),breaks=c(0,.2,.4,.6),expand=expansion(mult=0))+labs(title=paste0(letter,"  Predicting follow-up ",domain),x="Held-out R-squared (95% CI)",y=NULL)+base_theme()}
